  /// FITS CROTA2 in degrees.
  CROTA2: double = nan;
  /// FITS PCi_j matrix, 4 values row-major (PC1_1, PC1_2, PC2_1, PC2_2),
  /// present only when the source supplies them.
  PC: [double];
  /// Observed solar radius in arcseconds (FITS RSUN_OBS).
