  /// End of life power output in Watts
  POWER_EOL:double;
  /// Conversion efficiency as fraction (0.0-1.0)
  EFFICIENCY:double;
  /// Degradation rate per year as fraction
  DEGRADATION_RATE:double;
  /// Number of panels per array
